import sys
import unicodedata
from collections import Counter

def normalize(s):
    return ''.join(
        c for c in unicodedata.normalize('NFD', s)
        if unicodedata.category(c) != 'Mn'
    )

def main():
    data = sys.stdin.read().splitlines()
    if len(data) < 2:
        return

    P = normalize(data[0].strip())
    A = normalize(data[1].strip())

    count = Counter(P)

    for ch in A:
        if ch == '*':
            continue
        if count[ch] == 0:
            print('N')
            return
        count[ch] -= 1

    print('S')

if __name__ == "__main__":
    main()
